class ComputeIsocontours(Node):

    def __init__(self, parent_node_id : str, num_contours : int):
        if correctness_checks_on():
            if num_contours < 1:
                raise Exception("Number of contours must be positive.")

        super().__init__(parent_node_id, types.Scalar, types.Contours, locals())

        self.num_contours = num_contours

    @classmethod
    def chat_description(cls):
        return "queued computing isocontours"

    @classmethod
    def description(cls):
        return 'Computes a certain number of isocontours uniformly distributed by function value for a scalar field.'

    @classmethod
    def param_descriptions(cls):
        return {'parent_node_id': 'The id of a node of type scalar corresponding to the scalar field '
                           'whose contours we are computing.',
         'num_contours': 'The number of contours that are to be computed.'}

    def _evaluation_logic(self, parent_data, time_step):
        scalar_vtk = servermanager.Fetch(parent_data.data)
        numPoints = scalar_vtk.GetNumberOfPoints()
        scalar_array = scalar_vtk.GetPointData().GetArray("Scalars_")
        scalar_range = scalar_array.GetRange()
        dimensions = scalar_vtk.GetDimensions()

        skip = int(numPoints/1000000)
        if skip == 0:
            skip = 1

        values = []
        for i in range(0, numPoints, skip):
            values.append(scalar_array.GetTuple1(i))

        numSampled = len(values)
        values.sort()

        contour_values = []

        for n in range(self.num_contours):
            query_idx = int( (n+1) / (self.num_contours+1) * numSampled )
            contour_values.append( values[query_idx] )

        print(contour_values)

        contours = Contour(Input=parent_data.data)
        contours.ContourBy = ['POINTS', 'Scalars_']
        contours.Isosurfaces = contour_values
        contours.PointMergeMethod = 'Uniform Binning'

        return types.Contours(contours, *scalar_range, dimensions)

class EmbedIsocontours(Node):

    def __init__(self, parent_node_id : str, colormap : str = "cool warm", tube_radius : float = 1.0):
        if correctness_checks_on():
            if colormap not in options_lists["colormaps"]:
                raise Exception(f"Colormap for EmbedIsocontours must match one of the valid options ({enumerate_list(colormaps)})")

        super().__init__(parent_node_id, types.Contours, types.ContourEmbedding, locals(), False, True)

        self.colormap = colormap
        self.tube_radius = tube_radius

    @classmethod
    def chat_description(cls):
        return "queued embedding isocontours"

    @classmethod
    def description(cls):
        return 'Creates a geometric embedding of isocontours of a scalar field.'

    @classmethod
    def param_descriptions(cls):
        return {'parent_node_id': 'The id of a node of type contours which should be embedded.',
         'colormap': 'What colormap should be used for the visualization. Must be one of '
                     'OPTIONS:colormaps.',
         'tube_radius': "The radius of the tube used to trace the contours (if 2D)"}

    @classmethod
    def guardrails(cls):
        return [
            Guardrail(
                get_prompt("guardrails", "isocontours_colormap"),
                "colormap_same_as_scalar_embedding",
                "Set to False if these isocontours are to be shown alongside a scalar field yet use a different colormap, "
                "and the user did not explicitly request this behavior",
                raise_on_tool_param_false(
                    "Cannot create this node because isocontours should use the same colormap as any scalar field "
                    "embedding shown alongside them (unless the user said otherwise)."
                ),
            ),
            Guardrail(
                get_prompt("guardrails", "isocontours_simplification"),
                "performed_on_unsimplified_filed",
                "Set to False if these isocontours are computed on a simplified scalar field and the user did not explicitly, "
                "request this",
                raise_on_tool_param_false(
                    "Cannot create this node because isocontours were created on a simplified scalar field even though the "
                    "user did not explicitly request this."
                )
            )
        ]

    def _evaluation_logic(self, parent_data, time_step):

        colormap = colormaps[self.colormap]
        lut = colormap.lookupTable(parent_data.min_, parent_data.max_)

        return types.ContourEmbedding(parent_data.contours, self.tube_radius, lut, parent_data.dimensions)

    def _evaluation_logic_partial_cache(self, parent_data, partial_cache, time_step):

        partial_cache.contours = parent_data.contours
        return partial_cache

