def generate_structured_grid_type(class_name, mcp_name, chat_name, array_names):

    def __init__(self, data):
        self.data = data

    def save(self, dirname):
        if not os.path.isdir(dirname):
            os.mkdir(dirname)

            SaveData(f"{dirname}/data.vti", self.data)

    def load(cls, dirname):
        vti = XMLImageDataReader(FileName=[f"{dirname}/data.vti"])
        vti.UpdatePipelineInformation()

        has_orders = True
        available_arrays = list(vti.PointArrayStatus.Available)

        for array_name in array_names:
            if f"{array_name}_Order" not in available_arrays:
                has_orders = False

        if has_orders:
            load_array_names = array_names + [array_name + "_Order" for array_name in array_names]
        else:
            load_array_names = array_names

        vti.PointArrayStatus = load_array_names
        vti.TimeArray = 'None'
        return cls(vti)

    return type(class_name, (NodeData,), {
        "__init__" : __init__,
        "save" : save,
        "load" : classmethod(load),
        "get_mcp_name" : classmethod(lambda cls: mcp_name),
        "get_chat_name" : classmethod(lambda cls: chat_name)
    })

