    def get_code_name(cls):
        return "field"

    def visualize(self, renderView):
        min_, max_ = servermanager.Fetch(self.data).GetPointData().GetArray("Scalars_").GetRange()
        display = Show(self.data, renderView, 'UniformGridRepresentation')

        outline = Outline(Input=self.data)
        tube = Tube(Input=outline)
        tube.Radius = max(self.dimensions) * 0.0025
        Show(tube, renderView, 'GeometryRepresentation')

        if is_2d(self.dimensions):
            LUT = GetColorTransferFunction('Scalars_')
            LUT.RGBPoints = self.colormap.lookupTable(min_, max_)
            LUT.ScalarRangeInitialized = 1.0

            display.Representation = 'Slice'
            display.ColorArrayName = ['POINTS', 'Scalars_']
            display.LookupTable = LUT
        else:
            tf_min, tf_max = float('inf'), -float('inf')
            opacity_tf_table = []

            for i,tup in enumerate(self.opacity_tf):
                value, opacity = tup

                opacity_tf_table.append(value)
                opacity_tf_table.append(opacity)
                opacity_tf_table.append(0.5)
                opacity_tf_table.append(0.0)

                if opacity == 0.0:
                    if i == len(self.opacity_tf) - 1 or self.opacity_tf[i+1][1] != 0.0:
                        tf_min = min(tf_min, value)

                    if i == 0 or self.opacity_tf[i-1][1] != 0.0:
                        tf_max = max(tf_max, value)
                else:
                    tf_min = min(tf_min,value)
                    tf_max = max(tf_max,value)

            LUT = GetColorTransferFunction('Scalars_')
            LUT.RGBPoints = self.colormap.lookupTable(tf_min, tf_max)
            LUT.ScalarRangeInitialized = 1.0

            PWF = GetOpacityTransferFunction('Scalars_')
            PWF.Points = opacity_tf_table
            PWF.ScalarRangeInitialized = 1

            display.Representation = 'Volume'
            display.ColorArrayName = ['POINTS', 'Scalars_']
            display.LookupTable = LUT
            display.ScalarOpacityFunction = PWF

        colorBar = GetScalarBar(LUT, renderView)
        colorBar.Title = 'Scalars_'
        colorBar.ComponentTitle = ''
        colorBar.Visibility = 0
        colorBar.TitleColor = [0.0, 0.0, 0.0]
        colorBar.LabelColor = [0.0, 0.0, 0.0]

        if self.color_bar:
            return GetDisplayProperties(self.data)

